-- The Classes Block (docs/blocks/classes.md): Fortune's Weave's Classes become a Block type of
-- their own, "classes" (Matt, 2026-11-11): the game's ladder of tiers with one entry per class (58),
-- each tier headed by its own card saying what the tier takes.
-- Generated by scripts/build-classes-migration.ts from src/data/pages/fortunes-weave-classes.ts.
--
-- RUN THIS, THEN supabase/seed-app.sql. The seed sets the Block's type to 'classes', which this
-- allows; run the seed first and it stops at that line with nothing changed, so just run this and
-- then the seed again. The seed adds the other 50 classes and the Divine tier's card (it never
-- overwrites a card that's already there), so they land whichever order things end up in.
--
--   * game_blocks.type may be 'classes'.
--   * The 12 class cards there today get their new content: the four tier summaries ("Beginner
--     classes"...) become the tiers' header cards (content.header = true), keeping their ids, and
--     the eight secret classes get their tier, exam ranks, unlock, skills and growth modifiers.
--     Revisions are append-only, so each gets a new revision on Stable.
--   * Only a card whose Stable content is still exactly its starter content is changed, so nothing
--     the community wrote is overwritten, and running this twice changes nothing the second time.
--   * A card with an open Draft (checking, open, approved or preview) is skipped: shipping that
--     Draft would replace the new content with the old. It's listed below for a moderator.
--
-- Safe to run twice.

alter table public.game_blocks drop constraint if exists game_blocks_type_check;
alter table public.game_blocks add constraint game_blocks_type_check
  check (type in ('collection', 'guide', 'checklist', 'timeline', 'characters', 'items', 'tierlist', 'classes'));

do $$
declare r jsonb; c record; rid bigint;
begin
  for r in select * from jsonb_array_elements($c$[{"slug":"beginner-classes","starter":{"name":"Beginner classes","source":"Fortune's Weave Codex (Sept 18, 2026): Game8, RPG Site, Polygon, IGN, fan wikis","description":"Each has a mastery skill that adds +1 to its main stats.","sections":[{"label":"Requires","text":"Level 5, Renown 1, Beginner License"},{"label":"Classes","text":"Diviner (Magic Basics)\nGladiator (Attack Basics)\nHunter (Hunting Basics)\nOrnius Rider (Offense Basics, can dismount)\nSoldier (Defense Basics)"}],"categories":{"Tier":"Beginner"}},"content":{"name":"Beginner classes","header":true,"order":1,"description":"Every unit's first step. Each class's mastery skill adds +1 to its main stats.","sections":[{"label":"How to unlock","text":"Level 5 · Renown 1 · Beginner License"}],"categories":{"Tier":"Beginner"},"source":"Guides, Nov 2026: gameoverdrive.com.br (exam ranks, locks), Pocket Tactics (skills, movement), KeenGamer (growth modifiers), allthings.how (mastery skills); Fortune's Weave Codex (unlocks)"}},{"slug":"specialty-classes","starter":{"name":"Specialty classes","source":"Fortune's Weave Codex (Sept 18, 2026): Game8, RPG Site, Polygon, IGN, fan wikis","description":"No secret classes in this tier.","sections":[{"label":"Requires","text":"Level 20, Renown 4, Specialty License"},{"label":"Classes","text":"Archer, Armored Knight, Armored Ornius Rider, Brigand\nCharioteer (new class), Light Cavalry, Myrmidon\nPriest, Pugilist, Rogue, Shaman, Wing Soldier"}],"categories":{"Tier":"Specialty"}},"content":{"name":"Specialty classes","header":true,"order":2,"description":"Twelve classes, none of them secret.","sections":[{"label":"How to unlock","text":"Level 20 · Renown 4 · Specialty License"}],"categories":{"Tier":"Specialty"},"source":"Guides, Nov 2026: gameoverdrive.com.br (exam ranks, locks), Pocket Tactics (skills, movement), KeenGamer (growth modifiers), allthings.how (mastery skills); Fortune's Weave Codex (unlocks)"}},{"slug":"advanced-classes","starter":{"name":"Advanced classes","source":"Fortune's Weave Codex (Sept 18, 2026): Game8, RPG Site, Polygon, IGN, fan wikis","description":"These unlock automatically. Secret Advanced classes are their own cards.","sections":[{"label":"Requires","text":"Level 35, Renown 8, Advanced License"},{"label":"Classes","text":"Shido, Warrior, Sniper, Forest Knight\nDreadnought, Bardinger, Ovate, Bishop"}],"categories":{"Tier":"Advanced"}},"content":{"name":"Advanced classes","header":true,"order":3,"description":"Eight open to everyone, nine more locked to a route, a quest or Part III. A class unlocked on one route opens on every route.","sections":[{"label":"How to unlock","text":"Level 35 · Renown 8 · Advanced License"}],"categories":{"Tier":"Advanced"},"source":"Guides, Nov 2026: gameoverdrive.com.br (exam ranks, locks), Pocket Tactics (skills, movement), KeenGamer (growth modifiers), allthings.how (mastery skills); Fortune's Weave Codex (unlocks)"}},{"slug":"master-classes","starter":{"name":"Master classes","spoiler":true,"flag":"unconfirmed","source":"Fortune's Weave Codex (Sept 18, 2026): Game8, RPG Site, Polygon, IGN, fan wikis","description":"Unlocked through Part III quests. The exact conditions are still being worked out.","sections":[{"label":"Requires","text":"Level 45, Part III"},{"label":"Classes","text":"Battlemaster, Bow Adept, Castle Knight, Druid\nOrichaldia (mounted), Sentinel, Shadow Seeker\nValkyrium (mounted), War Monk, Wiseman"}],"categories":{"Tier":"Master"}},"content":{"name":"Master classes","header":true,"order":4,"description":"Unlocked in Part III. Six of them need a god’s temple restored first.","sections":[{"label":"How to unlock","text":"Level 45 · Part III"}],"categories":{"Tier":"Master"},"source":"Guides, Nov 2026: gameoverdrive.com.br (exam ranks, locks), Pocket Tactics (skills, movement), KeenGamer (growth modifiers), allthings.how (mastery skills); Fortune's Weave Codex (unlocks)"}},{"slug":"blacksmith","starter":{"name":"Blacksmith","routes":["dietrich"],"flag":"disputed","source":"Fortune's Weave Codex (Sept 18, 2026): Game8, RPG Site, Polygon, IGN, fan wikis","description":"Makeshift. Only Polygon lists this unlock so far.","sections":[{"label":"Where","text":"Dietrich's route"},{"label":"Path","text":"Reach Smyrnos's Blessing level 1 and Renown 8"}],"categories":{"Tier":"Secret"}},"content":{"name":"Blacksmith","routes":["dietrich"],"flag":"disputed","sections":[{"label":"Exam needs","text":"Black Magic: D\nAxes: C"},{"label":"How to unlock","text":"Dietrich: reach Smyrnos's Blessing level 1 and Renown 8 (Polygon), or enhance ten combat arts (Pocket Tactics)."},{"label":"Mastery skill","text":"Makeshift: 10% chance a combat art uses no durability"},{"label":"Skills","text":"Makeshift\nBlack-Magic Seeker\nAxe Hit +5"}],"categories":{"Tier":"Advanced","Moves":"On foot"},"stats":{"hp":15,"str":10,"mag":10,"spd":0,"dex":5,"def":10,"res":10,"lck":0,"cha":5},"source":"Guides, Nov 2026: gameoverdrive.com.br (exam ranks, locks), Pocket Tactics (skills, movement), KeenGamer (growth modifiers), allthings.how (mastery skills); Fortune's Weave Codex (unlocks)"}},{"slug":"caladrius","starter":{"name":"Caladrius","routes":["cai"],"source":"Fortune's Weave Codex (Sept 18, 2026): Game8, RPG Site, Polygon, IGN, fan wikis","description":"Overtake.","sections":[{"label":"Where","text":"Cai's route"},{"label":"Path","text":"Castor's mentoring: \"Special Request from Pop\" (Renown 7)\nDeliver 2 Angelica"}],"categories":{"Tier":"Secret"}},"content":{"name":"Caladrius","routes":["cai"],"sections":[{"label":"Exam needs","text":"Riding: D\nBlack Magic: B"},{"label":"How to unlock","text":"Cai: Castor's mentoring, \"Special Request from Pop\" (Renown 7): deliver 2 Angelica."},{"label":"Mastery skill","text":"Overtake: Mov +1 for each defeat, up to +3, until the end of the next turn"},{"label":"Skills","text":"Black-Magic Seeker\nCombat Arts +1\nMount/Dismount\nOvertake"}],"categories":{"Tier":"Advanced","Moves":"Riding"},"stats":{"hp":15,"str":0,"mag":10,"spd":5,"dex":10,"def":10,"res":10,"lck":5,"cha":5},"source":"Guides, Nov 2026: gameoverdrive.com.br (exam ranks, locks), Pocket Tactics (skills, movement), KeenGamer (growth modifiers), allthings.how (mastery skills); Fortune's Weave Codex (unlocks)"}},{"slug":"cataphract","starter":{"name":"Cataphract","routes":["theodora"],"source":"Fortune's Weave Codex (Sept 18, 2026): Game8, RPG Site, Polygon, IGN, fan wikis","description":"Pavise.","sections":[{"label":"Where","text":"Theodora's route"},{"label":"Path","text":"Send Supplies of Ladon Loach and Steel Fish (Ch 9)"}],"categories":{"Tier":"Secret"}},"content":{"name":"Cataphract","routes":["theodora"],"flag":"disputed","sections":[{"label":"Exam needs","text":"Armor: E+\nRiding: D\nAxes: B\nSpears: B"},{"label":"How to unlock","text":"Theodora: Send Supplies of Ladon Loach and Steel Fish (Ch 9)."},{"label":"Mastery skill","text":"Pavise"},{"label":"Skills","text":"Combat Arts +1\nMount/Dismount"}],"categories":{"Tier":"Advanced","Moves":"Riding"},"stats":{"hp":15,"str":15,"mag":-5,"spd":-10,"dex":0,"def":10,"res":-5,"lck":0,"cha":5},"source":"Guides, Nov 2026: gameoverdrive.com.br (exam ranks, locks), Pocket Tactics (skills, movement), KeenGamer (growth modifiers), allthings.how (mastery skills); Fortune's Weave Codex (unlocks)"}},{"slug":"dancer","starter":{"name":"Dancer","routes":["leda"],"source":"Fortune's Weave Codex (Sept 18, 2026): Game8, RPG Site, Polygon, IGN, fan wikis","description":"Special Dance.","sections":[{"label":"Where","text":"Leda's route"},{"label":"Path","text":"Ch 9: \"Great Dancer's Successor\"\nDeliver a Hingosh from Baina Oasis"}],"categories":{"Tier":"Secret"}},"content":{"name":"Dancer","routes":["leda"],"sections":[{"label":"Exam needs","text":"Bows: B\nSwords: B"},{"label":"How to unlock","text":"Leda: Ch 9, \"Great Dancer's Successor\": deliver a Hingosh from Baina Oasis."},{"label":"Mastery skill","text":"Special Dance"},{"label":"Skills","text":"Special Dance\nCombat Arts +2\nDance"}],"categories":{"Tier":"Advanced","Moves":"On foot"},"stats":{"hp":15,"str":5,"mag":0,"spd":25,"dex":10,"def":0,"res":5,"lck":10,"cha":20},"source":"Guides, Nov 2026: gameoverdrive.com.br (exam ranks, locks), Pocket Tactics (skills, movement), KeenGamer (growth modifiers), allthings.how (mastery skills); Fortune's Weave Codex (unlocks)"}},{"slug":"dragoon","starter":{"name":"Dragoon","routes":["cai","theodora"],"source":"Fortune's Weave Codex (Sept 18, 2026): Game8, RPG Site, Polygon, IGN, fan wikis","description":"Besieger.","sections":[{"label":"Where","text":"Cai or Theodora"},{"label":"Path","text":"Cai: Aurora's mentoring (\"Special Request from Mom\", Renown 8)\nTheodora: Send Supplies of Lir Fish and Sea-Star Stone (Ch 11)"}],"categories":{"Tier":"Secret"}},"content":{"name":"Dragoon","routes":["cai","theodora"],"sections":[{"label":"Exam needs","text":"Flying: C\nAxes: B\nSpears: B"},{"label":"How to unlock","text":"Cai: Aurora's mentoring, \"Special Request from Mom\" (Renown 8).\nTheodora: Send Supplies of Lir Fish and Sea-Star Stone (Ch 11)."},{"label":"Mastery skill","text":"Besieger: Hit +20 when the foe stands on favorable terrain"},{"label":"Skills","text":"Besieger\nMount/Dismount\nCombat Arts +1"}],"categories":{"Tier":"Advanced","Moves":"Flying"},"stats":{"hp":15,"str":5,"mag":0,"spd":0,"dex":5,"def":10,"res":10,"lck":10,"cha":5},"source":"Guides, Nov 2026: gameoverdrive.com.br (exam ranks, locks), Pocket Tactics (skills, movement), KeenGamer (growth modifiers), allthings.how (mastery skills); Fortune's Weave Codex (unlocks)"}},{"slug":"guardian","starter":{"name":"Guardian","routes":["dietrich","theodora"],"source":"Fortune's Weave Codex (Sept 18, 2026): Game8, RPG Site, Polygon, IGN, fan wikis","description":"Brace.","sections":[{"label":"Where","text":"Dietrich or Theodora"},{"label":"Path","text":"Dietrich: beat Il-Lara (Dread Warrior, Ch 9)\nTheodora: Send Supplies of Roca and Kothar Gar (Ch 9)"}],"categories":{"Tier":"Secret"}},"content":{"name":"Guardian","routes":["dietrich","theodora"],"flag":"disputed","sections":[{"label":"Exam needs","text":"Spears: B"},{"label":"How to unlock","text":"Dietrich: beat Il-Lara, the Dread Warrior (Ch 9).\nTheodora: Send Supplies of Roca and Kothar Gar (Ch 9)."},{"label":"Mastery skill","text":"Brace"},{"label":"Skills","text":"Combat Arts +2"}],"categories":{"Tier":"Advanced","Moves":"On foot"},"stats":{"hp":10,"str":10,"mag":0,"spd":0,"dex":5,"def":10,"res":15,"lck":5,"cha":5},"source":"Guides, Nov 2026: gameoverdrive.com.br (exam ranks, locks), Pocket Tactics (skills, movement), KeenGamer (growth modifiers), allthings.how (mastery skills); Fortune's Weave Codex (unlocks)"}},{"slug":"ranger","starter":{"name":"Ranger","routes":["leda"],"source":"Fortune's Weave Codex (Sept 18, 2026): Game8, RPG Site, Polygon, IGN, fan wikis","description":"Countershot.","sections":[{"label":"Where","text":"Leda's route"},{"label":"Path","text":"Finish \"Elegant Drink Recipes\""}],"categories":{"Tier":"Secret"}},"content":{"name":"Ranger","routes":["dietrich","leda"],"flag":"unconfirmed","sections":[{"label":"Exam needs","text":"Bows: B\nSwords: B"},{"label":"How to unlock","text":"Leda: finish \"Elegant Drink Recipes\".\nDietrich: win the Dread Warrior battles (two guides list this; our codex doesn't)."},{"label":"Mastery skill","text":"Countershot: 50% chance to counter adjacent foes with a bow"},{"label":"Skills","text":"Countershot\nCombat Arts +2\nLocktouch\nAdvanced Search"}],"categories":{"Tier":"Advanced","Moves":"On foot"},"stats":{"hp":10,"str":5,"mag":0,"spd":15,"dex":15,"def":0,"res":10,"lck":15,"cha":0},"source":"Guides, Nov 2026: gameoverdrive.com.br (exam ranks, locks), Pocket Tactics (skills, movement), KeenGamer (growth modifiers), allthings.how (mastery skills); Fortune's Weave Codex (unlocks)"}},{"slug":"troubadour","starter":{"name":"Troubadour","routes":["cai","leda"],"source":"Fortune's Weave Codex (Sept 18, 2026): Game8, RPG Site, Polygon, IGN, fan wikis","description":"Song of Courage.","sections":[{"label":"Where","text":"Cai or Leda"},{"label":"Path","text":"Cai: Bertrand's mentoring (\"White-Maned Demon's Request\", Renown 10)\nLeda: \"Elegant Drink Recipes\""}],"categories":{"Tier":"Secret"}},"content":{"name":"Troubadour","routes":["cai","leda"],"sections":[{"label":"Exam needs","text":"Riding: D\nBlack Magic: B\nWhite Magic: B"},{"label":"How to unlock","text":"Cai: Bertrand's mentoring, \"White-Maned Demon's Request\" (Renown 10).\nLeda: finish \"Elegant Drink Recipes\"."},{"label":"Mastery skill","text":"Song of Courage"},{"label":"Skills","text":"Magic Heal +5\nMagic Hit +3\nMount/Dismount"}],"categories":{"Tier":"Advanced","Moves":"Riding"},"stats":{"hp":10,"str":0,"mag":15,"spd":5,"dex":0,"def":5,"res":15,"lck":15,"cha":10},"source":"Guides, Nov 2026: gameoverdrive.com.br (exam ranks, locks), Pocket Tactics (skills, movement), KeenGamer (growth modifiers), allthings.how (mastery skills); Fortune's Weave Codex (unlocks)"}}]$c$::jsonb) loop
    select k.id, v.content into c
    from public.cards k
    join public.card_pointers p on p.card_id = k.id and p.channel = 'stable'
    join public.card_revisions v on v.id = p.revision_id
    where k.game_id = 'fortunes-weave' and k.block_key = 'classes' and k.slug = r->>'slug';
    -- Matched by the card's slug, its fixed key. A card the community has edited keeps its words.
    continue when c.id is null or c.content <> (r->'starter');
    if exists (select 1 from public.drafts d where d.card_id = c.id and d.status in ('checking', 'open', 'approved', 'preview')) then
      raise notice 'Skipped % : it has an open Draft', r->>'slug';
      continue;
    end if;
    insert into public.card_revisions (card_id, content, summary)
    values (c.id, r->'content', 'Classes Block: tier, exam ranks, skills and growth modifiers')
    returning id into rid;
    update public.card_pointers set revision_id = rid, updated_at = now() where card_id = c.id and channel = 'stable';
  end loop;
end $$;

-- Class cards skipped for an open Draft (expected: none). A moderator decides each by hand.
select k.slug, d.id as draft, d.status
from public.drafts d join public.cards k on k.id = d.card_id
where k.game_id = 'fortunes-weave' and k.block_key = 'classes' and d.status in ('checking', 'open', 'approved', 'preview');

-- What the 12 cards that were there say now: "Classes Block: ..." for each one changed (expected: all
-- 12, the four headers with header = true).
select k.slug, v.summary, v.content->'categories'->>'Tier' as tier, (v.content->>'header')::boolean as header
from public.cards k
join public.card_pointers p on p.card_id = k.id and p.channel = 'stable'
join public.card_revisions v on v.id = p.revision_id
where k.game_id = 'fortunes-weave' and k.block_key = 'classes' order by k.position;
